import{_ as r,o as a,c as e,ag as o}from"./chunks/framework.Aev9KvMf.js";const g=JSON.parse('{"title":"健康考证骗局拆解 · 健康管理师/公共营养师营销话术","description":"健康类考证骗局逐条拆解：健康管理师/公共营养师退出目录的时间线、六大战术话术对照、报名前四查与维权路径。","frontmatter":{"title":"健康考证骗局拆解 · 健康管理师/公共营养师营销话术","issuer":"综合人社部目录政策与官方核验渠道整理","source_tier":"一级来源","version":"—","published":"—","source_url":"http://zscx.osta.org.cn/","status":"现行政策","tags":["官方查询","考证","健康管理师","公共营养师","防坑","话术拆解"],"type":"查询页","reviewed":false,"description":"健康类考证骗局逐条拆解：健康管理师/公共营养师退出目录的时间线、六大战术话术对照、报名前四查与维权路径。"},"headers":[],"relativePath":"query/health-cert-scam.md","filePath":"query/health-cert-scam.md"}'),d={name:"query/health-cert-scam.md"};function s(h,t,l,n,u,i){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="健康考证骗局拆解-·-健康管理师-公共营养师营销话术" tabindex="-1">健康考证骗局拆解 · 健康管理师/公共营养师营销话术 <a class="header-anchor" href="#健康考证骗局拆解-·-健康管理师-公共营养师营销话术" aria-label="Permalink to &quot;健康考证骗局拆解 · 健康管理师/公共营养师营销话术&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">初稿待人工校验</p><p>本页由 AI 依据人社部公开政策与官方核验渠道整理；涉及证书退出目录的时间点等请以人社部文件为准（标待核验处）。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>本页<strong>不否定健康管理师/公共营养师证书本身</strong>——经备案机构认定、官方可查的技能等级证书是真实有用的。本页拆解的是<strong>围绕它的过度营销与骗局</strong>。</p></div><h2 id="事实时间线-拆解话术的地基" tabindex="-1">事实时间线（拆解话术的地基） <a class="header-anchor" href="#事实时间线-拆解话术的地基" aria-label="Permalink to &quot;事实时间线（拆解话术的地基）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时间</th><th>事实</th><th>出处</th></tr></thead><tbody><tr><td>2017 年</td><td>心理咨询师退出国家职业资格目录（待核验）</td><td>人社部目录文件</td></tr><tr><td>2020 年底</td><td><strong>水平评价类技能人员职业资格全部退出目录</strong>——健康管理师、公共营养师转为<strong>职业技能等级认定</strong>，由人社部备案的评价机构发证（待核验）</td><td>人社部文件</td></tr><tr><td>现在</td><td>这类证书可在<a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">技能人才评价证书全国联网查询</a>查到——但它们<strong>不是&quot;国家职业资格证&quot;</strong></td><td><a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">查询系统</a></td></tr></tbody></table><h2 id="六大战术话术拆解" tabindex="-1">六大战术话术拆解 <a class="header-anchor" href="#六大战术话术拆解" aria-label="Permalink to &quot;六大战术话术拆解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>话术</th><th>拆解</th></tr></thead><tbody><tr><td>①&quot;国家取消的是旧证，我们这是<strong>新版国家证书</strong>&quot;</td><td>半真半假：证书真实存在，但性质是<strong>技能等级证书</strong>，不是国家职业资格——&quot;国家证书&quot;是刻意模糊</td></tr><tr><td>②&quot;考完<strong>挂靠</strong>，躺着年入几万&quot;</td><td>健康类证书无挂靠市场，卫健系统执业不认此类证书；&quot;挂靠费&quot;是话术钩子</td></tr><tr><td>③&quot;<strong>政策改革前的最后一批</strong>，再不考就报不了&quot;</td><td>退出目录是 2020 年完成的既定事实，&quot;末班车&quot;话术每年都发一遍</td></tr><tr><td>④&quot;考完能<strong>领补贴回血</strong>，等于免费&quot;</td><td>补贴真实存在但有严格条件（参保 12 个月、目录/等级可查、12 个月内申领）——见<a href="/SageRelay/query/skill-subsidy.html">技能提升补贴</a>；<strong>补贴直接发个人</strong>，&quot;机构代收补贴&quot;是坑</td></tr><tr><td>⑤&quot;<strong>国际认证</strong> ACI 注册营养师，比国内的高级&quot;</td><td>境外/协会证书不在国家目录内，境内无执业效力</td></tr><tr><td>⑥&quot;今天优惠最后一天，明天<strong>涨价</strong>&quot;</td><td>制造紧迫阻止你核验——先做完&quot;报名前四查&quot;再说</td></tr></tbody></table><h2 id="报名前四查-行动清单" tabindex="-1">报名前四查（行动清单） <a class="header-anchor" href="#报名前四查-行动清单" aria-label="Permalink to &quot;报名前四查（行动清单）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>查什么</th><th>入口</th></tr></thead><tbody><tr><td>①查目录：这证是国家职业资格还是技能等级证书？</td><td><a href="/SageRelay/query/cert-search.html">考证防坑 · 目录核对</a></td></tr><tr><td>②查证书可查性：发证机构在人社部<strong>备案评价机构</strong>名单内吗？历届证书<a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">联网可查</a>吗？</td><td><a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">查询系统</a></td></tr><tr><td>③查机构底细：培训公司有行政处罚/经营异常吗？</td><td><a href="/SageRelay/query/enterprise-credit.html">企业信用查询</a></td></tr><tr><td>④查承诺兑现路径：&quot;包补贴&quot;的补贴谁申领、打到谁的卡？</td><td><a href="/SageRelay/query/skill-subsidy.html">技能提升补贴</a></td></tr></tbody></table><p><strong>已经交钱发现被骗</strong>：<a href="/SageRelay/query/samr-12315.html">12315 投诉举报</a>（虚假宣传）· <a href="/SageRelay/query/cca-315.html">消协智慧 315</a>。</p><h2 id="对照-仍然-硬-的健康类证书" tabindex="-1">对照：仍然&quot;硬&quot;的健康类证书 <a class="header-anchor" href="#对照-仍然-硬-的健康类证书" aria-label="Permalink to &quot;对照：仍然&quot;硬&quot;的健康类证书&quot;">​</a></h2><table tabindex="0"><thead><tr><th>证书</th><th>性质</th></tr></thead><tbody><tr><td>执业医师、护士执业资格</td><td>国家准入类职业资格（目录内）</td></tr><tr><td>注册营养师/注册营养技师</td><td>中国营养学会开展的水平评价认证——行业权威度高，但<strong>不在国家职业资格目录内</strong>（如实区分，待核验）</td></tr><tr><td>健康管理师/公共营养师（技能等级）</td><td>真实可查、对从业有证明力，但<strong>不是</strong>&quot;国家资格证&quot;、更无挂靠市场</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="/SageRelay/query/cert-search.html">考证防坑 · 证书查询与目录核对</a> · <a href="/SageRelay/query/skill-subsidy.html">技能提升补贴</a> · <a href="/SageRelay/query/enterprise-credit.html">企业信用</a> · <a href="/SageRelay/query/samr-12315.html">12315</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>政策</td><td>人社部国家职业资格目录及水平评价类退出文件（待核验）</td></tr><tr><td>核验</td><td><a href="http://zscx.osta.org.cn/" target="_blank" rel="noreferrer">osta 证书查询</a>（已核验可达）· 12333 · 12315</td></tr></tbody></table>',16)])])}const q=r(d,[["render",s]]);export{g as __pageData,q as default};
